        load  c_6
        store v_main__b
        load  c_0
        store v_main__res
while1: nop
        load  c_0
        store t1
        load  v_main__b
        sub   t1
        ifzero z3
        load  c_1
        goto  zend4
z3: load  c_0
zend4: nop
        ifzero endwhile2
        load  c_1
        store t2
        load  v_main__b
